-- MERA 2026/2027 liquid fuel retail licence register, valid as at 31 July 2026.
-- Names and locality labels come from the station titles. Postal addresses are intentionally not imported as site addresses.
-- This confirms licensing only; it does not confirm a station is currently open or has fuel.
-- Public register: https://mera.mw/download/lfg-valid-mera-licences-as-at-31st-july-2026/?wpdmdl=3775
alter table public.stations add column if not exists source text;
alter table public.stations add column if not exists source_url text;
alter table public.stations add column if not exists source_checked_at date;

update public.stations set source='MERA 2026/2027 retail licence register', source_url='https://mera.mw/download/lfg-valid-mera-licences-as-at-31st-july-2026/?wpdmdl=3775', source_checked_at='2026-07-31' where lower(name)=lower('Petroda Area 4') and lower(district)=lower('Lilongwe');
